import{_ as n,o as l,c as s,am as i}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"面试煎熬成蛋_SpringCloud","description":"","frontmatter":{"title":"面试煎熬成蛋_SpringCloud","excerpt":"面试煎熬成蛋_SpringCloud","date":"2024-03-10 20:15:10","updated":"2024-03-10 20:15:10"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_SpringCloud.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_SpringCloud.md","lastUpdated":null}'),e={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_SpringCloud.md"};function p(o,a,t,r,c,u){return l(),s("div",null,[...a[0]||(a[0]=[i(`<h3 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h3><h4 id="什么是-springcloud" tabindex="-1">什么是 SpringCloud <a class="header-anchor" href="#什么是-springcloud" aria-label="Permalink to &quot;什么是 SpringCloud&quot;">​</a></h4><p>SpringCloud 作为 Spring 家族重要的一环，它整合了多种微服务解决方案，为微服务架构提供了全面的支持，使得开发者可以更加专注于业务逻辑而非基础设施。</p><p>SpringCloud 通过Spring Boot风格进行封装，使得开发者可以轻松地构建分布式系统的各种组件。</p><h4 id="springcloud-vs-springboot" tabindex="-1">SpringCloud VS SpringBoot <a class="header-anchor" href="#springcloud-vs-springboot" aria-label="Permalink to &quot;SpringCloud VS  SpringBoot&quot;">​</a></h4><ul><li>Spring Boot ，专注于快速，方便的开发单个微服务个体。</li><li>Spring Cloud ，关注全局的服务治理框架。</li></ul><h4 id="说一下常用组件-🚩" tabindex="-1">说一下常用组件 🚩 <a class="header-anchor" href="#说一下常用组件-🚩" aria-label="Permalink to &quot;说一下常用组件  🚩&quot;">​</a></h4><p>Spring Cloud Netflix 第一代</p><ul><li>Eureka 注册中心</li><li>Ribbon 负载均衡</li><li>Feign 远程调用</li><li>Hystrix 服务熔断</li><li>Zuul 网关</li></ul><p>Spring Cloud Alibaba 第二代</p><ul><li>Nacos 注册中心、配置中心</li><li>Ribbon 负载均衡</li><li>OpenFeign 远程调用</li><li>Sentinel 服务保护</li><li>Gateway 网关</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311221942122.png" alt="image.png"></p><h4 id="讲一下-cap" tabindex="-1">讲一下 CAP <a class="header-anchor" href="#讲一下-cap" aria-label="Permalink to &quot;讲一下 CAP&quot;">​</a></h4><ul><li>一致性</li><li>可用性</li><li>分区容错性</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281656511.png" alt="image.png"></p><ul><li><strong>一致性（Consistency）</strong>：所有节点上的数据在同一时间是相同的。即在分布式系统中，每次读取操作都能得到最新的写入结果。一致性确保了系统的数据副本之间能够达成一致的状态。</li><li><strong>可用性（Availability）</strong>：每个请求都能在有限的时间内收到一个明确的响应，无论响应是成功的还是失败的。可用性保证了系统能够持续响应客户端的请求。</li><li><strong>分区容错性（Partition tolerance）</strong>：系统能够在任意网络分区发生时继续运行。分区容错性指的是，即使系统内部发生了网络分割，使得某些节点之间无法通信，系统仍然能够对外提供满足一致性或可用性的服务。</li></ul><p>实际应用：</p><p>在实际的分布式系统设计中，CAP定理提供了一个理论框架来指导如何在一致性、可用性和分区容错性之间做出权衡。不同的系统可能会根据自身的业务需求和特点，选择适合自己的CAP平衡点：</p><ul><li><strong>CA系统</strong>：放弃分区容错性，通常适用于单一数据中心的传统数据库系统。</li><li><strong>CP系统</strong>：放弃可用性，适用于对数据一致性要求极高的系统</li><li><strong>AP系统</strong>：放弃一致性，适用于对可用性要求极高的系统</li></ul><p>在分布式环境中，系统节点之间肯定的需要有网络连接的，因此分区（P) 是必然存在的</p><hr><p>在现实的分布式系统中，网络分区是不可避免的，因此分区容忍性（P）是必须要满足的。这就意味着我们只能在一致性（C）和可用性（A）之间做出选择。</p><ul><li><strong>AP系统</strong>：在网络分区发生时，选择保证可用性，但牺牲了一致性。这意味着在某些节点上可能读取到的是过时的数据，因为系统为了保证响应的可用性，允许在没有获取到最新数据副本的情况下也能响应客户端的读写请求。</li><li><strong>CP系统</strong>：在网络分区发生时，选择保证一致性，但可能牺牲可用性。这意味着如果数据不能在所有节点间同步，系统可能会拒绝处理读写请求，以保证不会返回错误或过时的数据。</li></ul><h4 id="讲一下-base" tabindex="-1">讲一下 Base <a class="header-anchor" href="#讲一下-base" aria-label="Permalink to &quot;讲一下 Base&quot;">​</a></h4><p>BASE理论是对CAP理论的一种补充和延伸，主要面向大规模分布式系统，在牺牲强一致性的前提下，追求系统的可用性和性能。</p><p>BASE是三个英文单词的缩写，分别代表：</p><ul><li><strong>基本可用（Basically Available）</strong>：系统允许分布式系统在出现故障的时候，保持核心可用，但是允许部分暂时不可用。这意味着在一些情况下（如网络分区、系统故障），系统仍然能提供基本的服务，即使这些服务可能是降级的。</li><li><strong>软状态（Soft State）</strong>：系统的状态不需要实时一致，允许系统中的数据存在中间状态，并认为这种状态是正常的。与之相对的是传统数据库中数据的“硬状态”，必须保证数据在任何时刻都是一致的。软状态允许系统在不同节点间数据同步存在延迟。</li><li><strong>最终一致性（Eventual Consistency）</strong>：系统保证在没有新的更新操作的情况下，数据最终会达到一致的状态。最终一致性强调的是，所有的更新操作最终将会传播到所有节点上，但并不保证更新操作的实时性和顺序性。</li></ul><p>BASE理论提供了一种面向可用性和性能的、对一致性要求相对宽松的设计和实现分布式系统的方法论，强调通过牺牲一致性来获得高可用性和高性能的可能性。</p><blockquote><p>示例：基于Base 理论实现分布式事务</p></blockquote><blockquote><p>面试题：解释一下 CAP 和 BASE</p></blockquote><ul><li>CAP定理（一致性.可用性、分区容错性） <ul><li>1.分布式系统节点通过网格连接。一定会出现分区问题(P)</li><li>2.当分区出现时，系统的一致性(C)和可用性(A)就无法同时满足</li></ul></li><li>BASE理论 <ul><li>1,基本可用</li><li>2.软状态</li><li>3.最终一致</li></ul></li><li>解决分布式事务的思想和模型： <ul><li>1,最终一致思想：各分支事务分别执行并提交，如果有不一致的情况，再想办法恢复数据(AP)</li><li>2.强一致思想：各分支事务执行完业务不要提交。等待彼此结果，而后统一提交或回滚(CP)</li></ul></li></ul><p>这个理解有点问题，待后续回顾一下 to be contined....</p><h3 id="nacos" tabindex="-1">Nacos <a class="header-anchor" href="#nacos" aria-label="Permalink to &quot;Nacos&quot;">​</a></h3><h4 id="nacos-和-eureka-的区别有哪些" tabindex="-1">Nacos 和 Eureka 的区别有哪些？ <a class="header-anchor" href="#nacos-和-eureka-的区别有哪些" aria-label="Permalink to &quot;Nacos 和 Eureka 的区别有哪些？&quot;">​</a></h4><ul><li>Nacos 和 Eureka 的共同点（注册中心） <ul><li>1、都支持服务注册和服务拉取</li><li>2、都支持服务提供者心跳方式做健康检测</li></ul></li><li>Nacos与Eureka的区别（注册中心） <ul><li>1、Nacos 支持服务端主动检测提供者状态：临时实例采用心跳模式，非临时实例采用主动检测模式</li><li>2、临时实例心桃不正常会被剔除，非临时实例则不会被剔除</li><li>3、Nacos 支持服务列表变更的消息推送模式，服务列表更新更及时</li><li>4、Nacos集群默认采用AP方式，当集群中存在非临时实例时，采用CP模式；Eureka采用AP方式</li></ul></li><li>Nacos还支持了配置中心，eureka则只有注册中心，也是选择使用nacos的一个重要原因</li></ul><h4 id="讲一下-nacos-的工作流程" tabindex="-1">讲一下 Nacos 的工作流程 <a class="header-anchor" href="#讲一下-nacos-的工作流程" aria-label="Permalink to &quot;讲一下 Nacos 的工作流程&quot;">​</a></h4><ul><li>服务发现 <ul><li>服务注册，服务发现，健康检查，服务注销</li></ul></li><li>配置管理</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315134919.png" alt="image.png"></p><h4 id="为什么要用配置中心" tabindex="-1">为什么要用配置中心 <a class="header-anchor" href="#为什么要用配置中心" aria-label="Permalink to &quot;为什么要用配置中心&quot;">​</a></h4><p>进行动态配置和统一管理</p><h4 id="常用的配置中心有哪些" tabindex="-1">常用的配置中心有哪些 <a class="header-anchor" href="#常用的配置中心有哪些" aria-label="Permalink to &quot;常用的配置中心有哪些&quot;">​</a></h4><p>Apollo和Nacos两者都是国内公司开源的知名项目，项目社区都比较活跃且都还在维护中。</p><p>Nacos是阿里开源的，Apollo是携程开源的。</p><p>Nacos使用起来比较简单，并且还可以直接用来做服务发现及管理。</p><p>Apollo 只能用来做配置管理，使用相对复杂些。</p><p>如果你的项目仅仅需要配置中心的话，建议使用 Apollo。如果你的项目需要配置中心的同时还需要服务发现及管理的话，那就更建议使用Nacos。</p><p>大概讲一下 Nacos 配置中心是怎么用的，然后带一下 说知道有 Apollo 这个东西，但没有用过。</p><h4 id="nacos-是去中心的吗-如果服务挂了-是否可以继续进行访问操作" tabindex="-1">Nacos 是去中心的吗，如果服务挂了，是否可以继续进行访问操作 <a class="header-anchor" href="#nacos-是去中心的吗-如果服务挂了-是否可以继续进行访问操作" aria-label="Permalink to &quot;Nacos 是去中心的吗，如果服务挂了，是否可以继续进行访问操作&quot;">​</a></h4><p>参考： <a href="https://wenku.csdn.net/answer/c5a9f976aa15481caf8ac84f2e036e46" target="_blank" rel="noreferrer">https://wenku.csdn.net/answer/c5a9f976aa15481caf8ac84f2e036e46</a></p><p>Nacos 一般会有两种模式，一种是集群模式，还有一种是持久化模式</p><ul><li>集群模式下，如果一个节点挂了，其他节点仍然是能提供后续服务</li><li>持久化模式下，nacos 服务如果挂了，服务之间仍然可以通过本地保存的注册信息进行通信。</li></ul><p>nacos的挂掉对服务之间的相互访问有影响，但可以通过 nacos 的集群模式和持久化模式来避免这种影响。</p><h3 id="openfeign" tabindex="-1">OpenFeign <a class="header-anchor" href="#openfeign" aria-label="Permalink to &quot;OpenFeign&quot;">​</a></h3><h4 id="openfeign-的原理你了解吗-🚩" tabindex="-1">OpenFeign 的原理你了解吗 🚩 <a class="header-anchor" href="#openfeign-的原理你了解吗-🚩" aria-label="Permalink to &quot;OpenFeign 的原理你了解吗 🚩&quot;">​</a></h4><p>OpenFeign 通过动态代理的方式封装了一系统操作，比如：建立连接、构造请求、发起靕求、获取响应、解析响应等</p><p>大概讲一下实现原理</p><ul><li><p>在默认配置下，Feign 客户端会与 Ribbon 和 Hystrix 集成，以提供负载均衡和断路器功能</p></li><li><p>首先，如果你对某个接口定义了 @FeignClient 注解，Feign就会针对这个接口创建一个动态代理</p></li><li><p>你要是调用那个接口，本质就是会调用 Feign创建的动态代理，这是核心中的核心</p></li><li><p>Feign的动态代理会根据你在接口上的@RequestMapping等注解，来动态构造出你要请求的服务的地址</p></li><li><p>最后针对这个地址，发起请求、解析响应</p></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240515114251.png" alt="image.png"></p><p>一般代码使用</p><ul><li>1、启动类上添加 @EnableFeignClients 注解</li><li>2、使用 <code>@FeignClient</code> 注解定义接口，并指定需要调用的服务名称</li><li>3、Controller 层正常提供对外的 RestController 接口</li></ul><h4 id="远程调用的时候你遇到过什么问题-怎么解决的-🚩" tabindex="-1">远程调用的时候你遇到过什么问题，怎么解决的 🚩 <a class="header-anchor" href="#远程调用的时候你遇到过什么问题-怎么解决的-🚩" aria-label="Permalink to &quot;远程调用的时候你遇到过什么问题，怎么解决的  🚩&quot;">​</a></h4><p>遇到过一些问题</p><ul><li>网络超时，接口调用时间过长 <ul><li><strong>配置超时时间</strong>：在远程调用时，设置合理的超时时间，避免长时间的阻塞。 <ul><li>在 Spring Cloud Feign 中可以配置超时时间：</li></ul></li><li><strong>使用熔断器</strong>：采用熔断机制（如 Hystrix 或 Resilience4j），在多次调用失败后断开连接，防止系统过载。 <ul><li>fallback 方法</li></ul></li></ul></li><li>服务不可用 <ul><li><strong>服务降级</strong>：通过熔断器或其他方式提供降级策略，在服务不可用时返回默认值或缓存数据。</li><li><strong>重试机制</strong>：配置重试策略，在调用失败后重试几次，以应对临时性的问题。</li></ul></li><li>负载不均衡</li><li>数据一致性 <ul><li>确保这种调用，最后能够保证最终一致性</li></ul></li><li>安全性问题 <ul><li>使用 OAuth2 或 JWT 对远程调用进行身份验证和授权</li><li>使用 HTTPS 或其他加密协议保护数据传输安全</li></ul></li><li>定位问题 <ul><li>远程调用失败时，调试和监控困难，难以快速定位问题。 <ul><li>在远程调用前后记录详细的日志信息，便于排查问题。</li><li>使用分布式跟踪系统（如 Zipkin 或 Jaeger）跟踪远程调用链路，分析性能瓶颈</li></ul></li></ul></li></ul><h4 id="讲一下-openfeign-的-fallback-原理" tabindex="-1">讲一下 OpenFeign 的 Fallback 原理 <a class="header-anchor" href="#讲一下-openfeign-的-fallback-原理" aria-label="Permalink to &quot;讲一下 OpenFeign 的 Fallback 原理&quot;">​</a></h4><h4 id="远程调用整个架构怎么设计的-少的话几个-多的话几百个、上千个接口如何管理" tabindex="-1">远程调用整个架构怎么设计的，少的话几个，多的话几百个、上千个接口如何管理？ <a class="header-anchor" href="#远程调用整个架构怎么设计的-少的话几个-多的话几百个、上千个接口如何管理" aria-label="Permalink to &quot;远程调用整个架构怎么设计的，少的话几个，多的话几百个、上千个接口如何管理？&quot;">​</a></h4><ul><li>服务注册与发现</li><li>负载均衡</li><li>API 管理平台</li></ul><p>扩展</p><ul><li>缓存</li><li>限流与熔断</li><li>异步通信</li><li>监控日志</li></ul><h3 id="ribbon" tabindex="-1">Ribbon <a class="header-anchor" href="#ribbon" aria-label="Permalink to &quot;Ribbon&quot;">​</a></h3><h4 id="讲一下-ribbon-的作用" tabindex="-1">讲一下 Ribbon 的作用 <a class="header-anchor" href="#讲一下-ribbon-的作用" aria-label="Permalink to &quot;讲一下 Ribbon 的作用&quot;">​</a></h4><ul><li>均匀的把请求分发到各个机器上</li></ul><p>实现工作流程</p><ul><li>1、<strong>服务列表维护</strong>：Ribbon 从注册中心（如 Eureka、Nacos）获取服务实例列表，并定期更新。它维护一份本地缓存，包含所有可用服务实例的信息。</li><li>2、<strong>负载均衡策略</strong>：Ribbon 提供多种负载均衡策略（如轮询、随机、加权等），可以通过配置选择合适的策略。默认策略是轮询。</li><li>3、<strong>服务调用</strong>：在客户端发起请求时，Ribbon 会根据选定的负载均衡策略，从服务实例列表中选择一个实例，并将请求转发到该实例。</li></ul><h4 id="ribbon-常见的负载均衡策略有哪些" tabindex="-1">Ribbon 常见的负载均衡策略有哪些 <a class="header-anchor" href="#ribbon-常见的负载均衡策略有哪些" aria-label="Permalink to &quot;Ribbon 常见的负载均衡策略有哪些&quot;">​</a></h4><p>Ribbon 常见的负载均衡策略：</p><ul><li><strong>Round Robin Rule（轮询规则）</strong><ul><li>这是最简单也是最常用的负载均衡策略。它按顺序循环地选择服务实例，每次请求轮流分配给下一个服务实例。</li><li><strong>使用场景</strong>：适用于所有服务实例处理能力相当的情况。</li></ul></li><li><strong>Random Rule（随机规则）</strong><ul><li>随机选择一个服务实例。每次请求都是随机从服务列表中选取一个服务实例进行调用。</li><li><strong>使用场景</strong>：适用于服务实例众多，需要避免轮询带来的均匀性不足问题的场景。</li></ul></li><li><strong>Response Time Weighted Rule</strong>（响应时间加权规则） <ul><li>根据服务实例的平均响应时间来计算所有服务实例的权重，响应时间短的服务实例将有更高的权重，被更频繁地选择。</li><li><strong>使用场景</strong>：适用于服务实例性能差异较大，希望优先调用响应时间短的服务实例的情况。</li></ul></li><li>Retry Rule（重试规则） <ul><li>在一个指定的时间内，如果选定的服务实例不成功，则会重新选择一个服务实例进行尝试，直到获取成功响应或达到最大重试次数。</li><li><strong>使用场景</strong>：适用于对服务调用的可靠性要求较高的情况，可以增加调用成功的机会。</li></ul></li><li>Best Available Rule（最低并发规则） <ul><li>选择并发请求最小的服务实例。这个策略会考虑到服务实例的并发请求量，优先选择并发量最小的实例。</li><li><strong>使用场景</strong>：适用于需要平衡服务实例负载，避免某些实例过载的场景。</li></ul></li><li>Availability Filtering Rule（可用性过滤规则） <ul><li>先过滤掉一直连接失败的被标记为circuit tripped的服务实例，然后选择一个并发量最小的实例。</li><li><strong>使用场景</strong>：适用于需要剔除不稳定服务实例，确保服务调用的高可用性。</li></ul></li><li><strong>Zone Avoidance Rule</strong>（区域权重规则） <ul><li>综合区域的性能和服务实例的可用性来选择服务器。尽可能地选择一个较少负载且可用性较高的服务实例。</li><li>适用于跨多个区域（如AWS区域）部署的服务，需要考虑区域性能和可用性的场景。</li></ul></li></ul><p>一般问到负载均衡常用的策略也可以从常见的几个策略谈一下：轮询、随机、响应时间权重、区域权重。</p><p>具体的负载均衡策略配置是怎么操作的：</p><p>在Spring Cloud应用中，具体配置Ribbon的负载均衡策略通常涉及到application.properties或application.yml配置文件的修改，或者通过编码的方式自定义配置。</p><p>下面是两种常见的配置方法：</p><blockquote><p>通过配置文件配置</p></blockquote><p>在<code>application.yml</code>或<code>application.properties</code>中，可以为所有服务或特定服务设置负载均衡策略</p><p>application.yml示例</p><p>为所有服务设置轮询策略：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ribbon:</span></span>
<span class="line"><span>  NFLoadBalancerRuleClassName: com.netflix.loadbalancer.RoundRobinRule</span></span></code></pre></div><p>为特定服务设置随机策略：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user-service:</span></span>
<span class="line"><span>  ribbon:</span></span>
<span class="line"><span>    NFLoadBalancerRuleClassName: com.netflix.loadbalancer.RandomRule</span></span></code></pre></div><p>你也可以通过编写Java配置类来自定义Ribbon的负载均衡策略，这种方法更加灵活，允许更复杂的配置。</p><p>下面是一个为<code>user-service</code>服务自定义随机负载均衡策略的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import com.netflix.loadbalancer.IRule;</span></span>
<span class="line"><span>import com.netflix.loadbalancer.RandomRule;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Bean;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Configuration;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class RibbonConfiguration {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public IRule ribbonRule() {</span></span>
<span class="line"><span>        // 使用随机负载均衡策略</span></span>
<span class="line"><span>        return new RandomRule();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后，你需要在<code>application.properties</code>或<code>application.yml</code>中指定这个配置类应用于哪个服务：</p><p>application.yml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user-service:</span></span>
<span class="line"><span>  ribbon:</span></span>
<span class="line"><span>    NFLoadBalancerClassName: com.example.demo.config.RibbonConfiguration</span></span></code></pre></div><p>注意事项</p><ul><li>当通过编码方式自定义Ribbon配置时，确保不要将<code>@Configuration</code>配置类放在主应用程序上下文的<code>@ComponentScan</code>中，以避免该配置成为全局配置。推荐的做法是将Ribbon的配置类放在主应用类的包外，或者显式指定<code>@ComponentScan</code>的扫描路径排除这些配置。</li><li>Spring Cloud中，Feign已默认集成了Ribbon，所以通过Feign调用服务时，也可以利用这些负载均衡策略。</li></ul><p>通过这些方法，可以灵活地为应用配置合适的负载均衡策略，优化服务调用的性能和可靠性。</p><h4 id="讲一下自定义负载均衡策略" tabindex="-1">讲一下自定义负载均衡策略 <a class="header-anchor" href="#讲一下自定义负载均衡策略" aria-label="Permalink to &quot;讲一下自定义负载均衡策略&quot;">​</a></h4><ul><li>一般来说我们可以定义全局的负载均衡策略或者针对某一个服务进行单独的配置文件中定义</li><li>或者我们创建一个配置类，指定自定义负载均衡策略</li></ul><hr><p>在上文中实际已经讲述了自定义负载均衡策略的实现：</p><ul><li>1、创建类实现 IRule 接口，指定负载均衡策略（全局）</li><li>2、在客户端的配置文件中，配置某一个服务指定的负载均衡策略（局部）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281439113.png" alt="image.png"></p><blockquote><p>关于【创建类实现 IRule 接口，指定负载均衡策略】的进一步说明</p></blockquote><p>首先是这种方式和【在配置文件中为所有服务统一设置负载均衡策略】的区别：</p><ul><li>1、对于大多数标准使用场景，<strong>通过配置文件设置负载均衡策略</strong>更容易管理和调整。尤其是在微服务架构中，当服务数量较多时，能够快速统一调整策略。（后者的一个作用是简化配置）</li><li>2、通过编码方式实现<code>IRule</code>接口，可以创建一个自定义的负载均衡策略，这种方法提供了极高的灵活性和控制力。你可以根据具体的业务需求编写负载均衡逻辑，实现一些标准策略（如轮询、随机）之外的特殊需求。（前者可以定制化一些策略，不过复杂性会高一些）</li></ul><blockquote><p>针对【创建类实现 IRule 接口，指定负载均衡策略】是全局生效的进一步说明</p></blockquote><p>看了一种解释，是说：并不是都是全局，一般是全局，但是也可以针对特定服务。</p><p>创建类实现<code>IRule</code>接口来指定负载均衡策略，然后在Spring配置中将这个自定义的规则应用到Ribbon客户端上，这种做法可以是全局的，也可以是针对特定服务的，具体取决于如何配置这个自定义规则。</p><p>全局配置</p><p>如果你创建了一个实现<code>IRule</code>接口的类来定义一个自定义的负载均衡策略，并且在Spring的主配置类（<code>@SpringBootApplication</code>所在的类）中通过<code>@Bean</code>注解注册了这个规则，那么它会被应用为全局的负载均衡策略。</p><p>这意味着所有使用Ribbon客户端进行服务调用的地方都会使用这个自定义的负载均衡规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class RibbonConfiguration {</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public IRule ribbonRule() {</span></span>
<span class="line"><span>        return new MyCustomRule();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>特定服务配置</p><p>如果你想要将自定义的负载均衡策略应用到特定的服务上，而不是全局应用，你可以通过创建一个Ribbon的配置类并使用<code>@RibbonClient</code>注解来指定这个配置类应用到哪个服务上。这个配置类不应该被主应用程序上下文的<code>@ComponentScan</code>所扫描，以避免它成为全局配置。通常，这意味着将这个配置类放在主应用程序类所在包的外面，或者在<code>@ComponentScan</code>注解中显式排除它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class UserRibbonConfiguration {</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public IRule ribbonRule() {</span></span>
<span class="line"><span>        return new MyCustomRuleForUserService();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@RibbonClient(name = &quot;user-service&quot;, configuration = UserRibbonConfiguration.class)</span></span>
<span class="line"><span>public class ServiceConfig {</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，<code>MyCustomRuleForUserService</code>只会应用到<code>user-service</code>服务上，而不会影响其他服务。</p><p>区别</p><ul><li><strong>全局配置</strong>：通过在Spring主配置中注册自定义<code>IRule</code>实现，它会被应用到所有通过Ribbon调用的服务上。这种方式简单，但缺乏针对性。</li><li><strong>特定服务配置</strong>：通过为特定服务创建独立的Ribbon配置类并使用<code>@RibbonClient</code>注解来指定，可以实现对不同服务使用不同的负载均衡策略。这种方式提供了更高的灵活性和针对性。</li></ul><h4 id="负载均衡策略" tabindex="-1">负载均衡策略 <a class="header-anchor" href="#负载均衡策略" aria-label="Permalink to &quot;负载均衡策略&quot;">​</a></h4><p>获取 URL路径</p><h4 id="ribbon-的底层原理-🚩" tabindex="-1">Ribbon 的底层原理 🚩 <a class="header-anchor" href="#ribbon-的底层原理-🚩" aria-label="Permalink to &quot;Ribbon 的底层原理  🚩&quot;">​</a></h4><p>Ribbon 的底层原理包括<strong>获取服务实例列表、应用负载均衡策略选择服务实例</strong>、提供重试机制以及与服务发现组件的集成。</p><p>通过这些机制，Ribbon 可以在客户端实现高效的负载均衡，使得分布式系统中的服务调用更加稳定和高效。</p><h3 id="hystrix" tabindex="-1">Hystrix <a class="header-anchor" href="#hystrix" aria-label="Permalink to &quot;Hystrix&quot;">​</a></h3><h4 id="讲一下-hystrix-的作用" tabindex="-1">讲一下 hystrix 的作用 <a class="header-anchor" href="#讲一下-hystrix-的作用" aria-label="Permalink to &quot;讲一下 hystrix 的作用&quot;">​</a></h4><ul><li>Hystrix隔离、熔断和降级</li></ul><blockquote><p>一般如何使用的</p></blockquote><p>使用示例</p><p>在 Spring Boot 应用的主类上添加 <code>@EnableFeignClients</code> 和 <code>@EnableHystrix</code> 注解：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@SpringBootApplication</span></span>
<span class="line"><span>@EnableFeignClients</span></span>
<span class="line"><span>@EnableHystrix</span></span>
<span class="line"><span>public class Application {</span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        SpringApplication.run(Application.class, args);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用 <code>@FeignClient</code> 注解定义 Feign 客户端接口，并指定降级处理类</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.cloud.openfeign.FeignClient;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.GetMapping;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.RequestMapping;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@FeignClient(name = &quot;service-provider&quot;, fallback = HelloClientFallback.class)</span></span>
<span class="line"><span>public interface HelloClient {</span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    String sayHello();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>创建一个实现 <code>HelloClient</code> 接口的降级处理类：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.stereotype.Component;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Component</span></span>
<span class="line"><span>public class HelloClientFallback implements HelloClient {</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public String sayHello() {</span></span>
<span class="line"><span>        return &quot;Fallback response&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在控制器中使用 Feign 客户端：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.beans.factory.annotation.Autowired;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.GetMapping;</span></span>
<span class="line"><span>import org.springframework.web.bind.annotation.RestController;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@RestController</span></span>
<span class="line"><span>public class HelloController {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private HelloClient helloClient;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GetMapping(&quot;/hello&quot;)</span></span>
<span class="line"><span>    public String hello() {</span></span>
<span class="line"><span>        return helloClient.sayHello();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="服务雪崩是什么" tabindex="-1">服务雪崩是什么 <a class="header-anchor" href="#服务雪崩是什么" aria-label="Permalink to &quot;服务雪崩是什么&quot;">​</a></h4><p>服务雪崩是分布式系统中一个常见的问题，指的是当某个（或某些）微服务不可用或响应时间过长时，会导致调用该服务的其他服务也跟着变慢或不可用，这种情况会像雪崩一样向整个系统蔓延，最终可能导致整个系统崩溃。</p><ul><li>服务雪崩：一个服务失败，号致整条线路的服务都失败的情形</li><li>解决方案 <ul><li>服务降级：服务自我保护的一种方式，或者保护下游服务的一种方式，用于确保服务不会受请求突增影响变得不可用，确保服务不会崩溃，<strong>一般在实标开发中与 feign 接口整合，编写降级逻辑</strong></li><li>服务熔断：默认关闭。需要手动打开，如果检测到10秒内请求的失败率超过50%，就触发熔断机别。之后<strong>每隔 5秒重新尝试请求</strong>微服务，如果微服务不能响应，继续走熔断机制，如果微服务可达，则关闭熔断机制，恢复正常请求</li></ul></li></ul><p>服务雪崩</p><ul><li>如果某个服务不可用，依赖该服务的其他服务也无法正常工作，从而导致整个依赖链中的服务都不可用</li><li>可能造成现象的原有 <ul><li>1、资源耗尽，请求量太大了，服务处理不过来（没有进行限流）</li><li>2、服务挂了</li><li>3、配置问题</li></ul></li></ul><h3 id="gateway" tabindex="-1">Gateway <a class="header-anchor" href="#gateway" aria-label="Permalink to &quot;Gateway&quot;">​</a></h3><h4 id="讲一下-网关的作用" tabindex="-1">讲一下 网关的作用 <a class="header-anchor" href="#讲一下-网关的作用" aria-label="Permalink to &quot;讲一下 网关的作用&quot;">​</a></h4><ul><li>网关：如果前端、移动端要调用后端系统，统一从网关进入，由网关转发请求给对应的服务</li></ul><p>Eureka 那一套的流程，思路可以借鉴一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240515122004.png" alt="image.png"></p><p>Spring Cloud Gateway 是一个基于 Spring WebFlux 框架的API 网关，它提供了一种简单且有效的方式来路由请求、处理认证与授权、进行负载均衡、监控和限流等操作.</p><p>核心组件</p><ul><li>Route 路由 <ul><li><strong>Route</strong> 是 Gateway 中的基本构建块。每个 Route 都定义了一个匹配的条件（Predicate）和一个处理请求的逻辑（Filter）</li><li>Route 包含： <ul><li><strong>ID</strong>：唯一标识路由的字符串。</li><li><strong>URI</strong>：目标服务的地址。</li><li><strong>Predicates</strong>：一组条件，用于匹配请求。例如，根据请求路径、方法、头部等进行匹配。</li><li><strong>Filters</strong>：一组过滤器，用于对请求或响应进行处理</li></ul></li></ul></li><li>Predicate 谓词 <ul><li>Predicate 用于匹配进入的 HTTP 请求。如果请求匹配，则该请求会被路由到指定的 URI。</li><li>常见的谓词有：路径匹配、头部匹配、方法匹配等。</li></ul></li><li>Filter 过滤器 <ul><li>Filter 用于对请求和响应进行处理。可以在请求被路由之前或之后执行各种操作，例如修改请求头、限流、日志记录等。</li><li>过滤器分为两类： <ul><li><strong>Global Filters</strong>：全局过滤器，作用于所有路由。</li><li><strong>Route-Specific Filters</strong>：特定路由的过滤器，只作用于指定的路由。</li></ul></li></ul></li></ul><p>工作流程</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240515141756.png" alt="image.png"></p><p>示例</p><p>在 <code>application.yml</code> 中配置路由示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - id: example_route</span></span>
<span class="line"><span>          uri: http://example.com</span></span>
<span class="line"><span>          predicates:</span></span>
<span class="line"><span>            - Path=/example/**</span></span>
<span class="line"><span>          filters:</span></span>
<span class="line"><span>            - AddRequestHeader=Example, HeaderValue</span></span></code></pre></div><p>在这个配置中：</p><ul><li>定义了一个 ID 为 <code>example_route</code> 的路由。</li><li>当请求路径匹配 <code>/example/**</code> 时，请求会被转发到 <code>http://example.com</code>。</li><li>在请求被转发之前，会添加一个请求头 <code>Example: HeaderValue</code></li></ul><p>核心功能</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240515141953.png" alt="image.png"></p><ul><li>日志记录 <ul><li>一般会定义全局过滤器 GlobalFilter（继承），然后重写 filter 方法，在方法中记录请求和响应日志</li></ul></li><li>动态路由 <ul><li>一般结合 nacos 使用</li></ul></li><li>负载均衡 <ul><li>结合 Openfeign 使用，常见的一种用法</li></ul></li></ul><blockquote><p>动态路由</p></blockquote><p>在 <code>application.yml</code> 中配置 Nacos。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    nacos:</span></span>
<span class="line"><span>      discovery:</span></span>
<span class="line"><span>        server-addr: 127.0.0.1:8848</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      discovery:</span></span>
<span class="line"><span>        locator:</span></span>
<span class="line"><span>          enabled: true</span></span></code></pre></div><p>在 Nacos 控制台中，创建或修改路由配置，格式与 <code>application.yml</code> 类似。</p><blockquote><p>负载均衡</p></blockquote><p>Spring Cloud Gateway 默认使用 Spring Cloud LoadBalancer 进行负载均衡。以下是一些常见的配置和使用示例</p><p>在 <code>application.yml</code> 中配置负载均衡。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - id: loadbalancer_route</span></span>
<span class="line"><span>          uri: lb://service-provider</span></span>
<span class="line"><span>          predicates:</span></span>
<span class="line"><span>            - Path=/loadbalancer/**</span></span>
<span class="line"><span>          filters:</span></span>
<span class="line"><span>            - AddRequestHeader=LoadBalancer, HeaderValue</span></span></code></pre></div><p>这里 <code>lb://service-provider</code> 表示将请求负载均衡到 <code>service-provider</code> 服务实例上</p><h4 id="gateway-原理大概讲一下" tabindex="-1">Gateway 原理大概讲一下 <a class="header-anchor" href="#gateway-原理大概讲一下" aria-label="Permalink to &quot;Gateway 原理大概讲一下&quot;">​</a></h4><ol><li>请求匹配</li></ol><p>当客户端发出 HTTP 请求时，Gateway 会根据配置的 Route 和 Predicate 对请求进行匹配。匹配过程如下：</p><ol><li><p><strong>Predicate Matching</strong>：Gateway 会遍历所有的路由，根据 Predicate 对请求进行匹配，找到符合条件的路由。</p></li><li><p><strong>Filter Execution</strong>：对于匹配的路由，执行其配置的 Filter 以及全局 Filter。</p></li><li><p><strong>Request Forwarding</strong>：处理完过滤器后，将请求转发到 Route 定义的目标 URI（目标服务）。</p></li><li><p>请求处理流程</p></li><li><p><strong>客户端请求</strong>：客户端发送一个 HTTP 请求到 Gateway。</p></li><li><p><strong>请求匹配</strong>：Gateway 根据定义的 Route 和 Predicate 对请求进行匹配。</p></li><li><p><strong>过滤器链</strong>：如果请求匹配某个 Route，Gateway 会执行该 Route 上定义的 Filter 以及全局 Filter。</p></li><li><p><strong>请求转发</strong>：经过过滤器链处理后，请求会被转发到 Route 定义的 URI（目标服务）。</p></li><li><p><strong>响应处理</strong>：目标服务返回响应，Gateway 会再经过过滤器链处理响应，然后返回给客户端。</p></li></ol><h4 id="gateway-的版本区分" tabindex="-1">Gateway 的版本区分 <a class="header-anchor" href="#gateway-的版本区分" aria-label="Permalink to &quot;Gateway 的版本区分&quot;">​</a></h4><blockquote><p>版本差异</p></blockquote><ul><li><strong>2.0.x 版本</strong>：引入了基于WebFlux的反应式编程模型，不再使用传统的Servlet API。提供了基本的路由、过滤功能。</li><li><strong>2.1.x 版本</strong>：增加了对WebSocket的支持，改进了路由断言和过滤器的功能。</li><li><strong>2.2.x 版本</strong>：引入了更多的路由断言和过滤器，增强了安全性和可管理性。</li><li><strong>3.0.x 版本</strong>：更新了底层的Spring Boot和Spring Framework的版本，支持最新的功能，例如更好的错误处理和性能优化。</li></ul><p>一般说我们常见的是2.2 版本就行</p><h3 id="sentinel" tabindex="-1">Sentinel <a class="header-anchor" href="#sentinel" aria-label="Permalink to &quot;Sentinel&quot;">​</a></h3><h4 id="基本原理" tabindex="-1">基本原理 <a class="header-anchor" href="#基本原理" aria-label="Permalink to &quot;基本原理&quot;">​</a></h4><p>Sentinel 的限流主要是通过在方法或接口前后增加拦截逻辑来实现的。当请求达到某个接口或方法时，Sentinel 会检查当前的请求流量是否超过了预设的限流规则，如果超过则进行限流处理（如拒绝请求、排队等）</p><p>主要的限流方式</p><ol><li><strong>QPS（Queries Per Second）限流</strong>：基于每秒请求次数的限流。</li><li><strong>线程数限流</strong>：基于并发线程数的限流。</li><li><strong>流控排队模式</strong>：基于排队等待时间的限流</li></ol><p>Sentinel 控制台提供了可视化的限流规则配置界面，可以动态调整限流规则。</p><ul><li>1、控制台</li><li>2、代码配置</li><li>3、配置类</li></ul><h3 id="zipkin" tabindex="-1">Zipkin <a class="header-anchor" href="#zipkin" aria-label="Permalink to &quot;Zipkin&quot;">​</a></h3><ul><li>查询服务链路，并排查问题</li><li>监听服务问题，并及时反馈</li></ul><h3 id="xxl-job" tabindex="-1">Xxl-job <a class="header-anchor" href="#xxl-job" aria-label="Permalink to &quot;Xxl-job&quot;">​</a></h3><h4 id="你们项目中使用了什么分布式任务调度" tabindex="-1">你们项目中使用了什么分布式任务调度 <a class="header-anchor" href="#你们项目中使用了什么分布式任务调度" aria-label="Permalink to &quot;你们项目中使用了什么分布式任务调度&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228234452.png" alt="image.png"></p><h4 id="xxl-job-路由策略有哪些" tabindex="-1">xxl-job 路由策略有哪些？ <a class="header-anchor" href="#xxl-job-路由策略有哪些" aria-label="Permalink to &quot;xxl-job 路由策略有哪些？&quot;">​</a></h4><ul><li>轮询、故障转移、分片广播</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228234546.png" alt="image.png"></p><h4 id="xxl-job-任务执行失败怎么解决" tabindex="-1">xxl-job 任务执行失败怎么解决？ <a class="header-anchor" href="#xxl-job-任务执行失败怎么解决" aria-label="Permalink to &quot;xxl-job 任务执行失败怎么解决？&quot;">​</a></h4><p>重试 + 告警</p><p>设置故障转移 + 失败重试，查看日志分析 → 邮件告警</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228234701.png" alt="image.png"></p><h4 id="如果有大数据量的任务同时都需要执行-怎么解决" tabindex="-1">如果有大数据量的任务同时都需要执行，怎么解决？ <a class="header-anchor" href="#如果有大数据量的任务同时都需要执行-怎么解决" aria-label="Permalink to &quot;如果有大数据量的任务同时都需要执行，怎么解决？&quot;">​</a></h4><p>分片广播策略</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228234936.png" alt="image.png"></p><p>面试题回答；</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228235033.png" alt="image.png"></p><h3 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to &quot;分布式事务&quot;">​</a></h3><h4 id="讲一下分布式事务的方案有哪些-你们项目中怎么处理的" tabindex="-1">讲一下分布式事务的方案有哪些，你们项目中怎么处理的 <a class="header-anchor" href="#讲一下分布式事务的方案有哪些-你们项目中怎么处理的" aria-label="Permalink to &quot;讲一下分布式事务的方案有哪些，你们项目中怎么处理的&quot;">​</a></h4><p>参考这篇文章整合一下相关内容： <a href="https://www.yuque.com/snailclimb/mf2z3k/ng9vmg" target="_blank" rel="noreferrer">https://www.yuque.com/snailclimb/mf2z3k/ng9vmg</a></p><ul><li>简历上写的微服务，只要是发生了多个服务之间的<strong>写操作</strong>，都需要进行分布式事务控制</li><li>描述项目中采用的那种方案(seata|MQ) <ul><li>1.seata的XA模式，CP,需要互相等待各个分支事务提交，可以保证强一致性，性能差 银行业务</li><li>2.seata的AT模式，AP,底层使用undo log实现，性能好 互联网业务</li><li><ol start="3"><li>seata的TCC模式，AP,性能较好，不过需要人工编码实现 银行业务</li></ol></li></ul></li><li>4.MQ模式实现分布式事务，在A服务写数据的时候，需要在同一个事务内发送消息到另外一个事务，异步，性能最好 互联网业务</li></ul><hr><p>微服务项目</p><ul><li>Seata 框架（XA、AT、TCC）</li><li>MQ</li></ul><blockquote><p>Seata 📕</p></blockquote><p>Seata是一个开源的分布式事务解决方案，旨在提供高性能和简单易用的分布式事务服务。</p><p>在Seata中，主要提供了三种事务模式：XA、AT和TCC，以满足不同场景下的分布式事务需求。</p><hr><blockquote><p>Seata 架构</p></blockquote><p>Seata事务管理中有三个重要的角色：</p><ul><li>TC(Transaction Coordinator)-事务协调者：维护全局和分支事务的状态，协调全局事务提交或回滚。</li><li>TM(Transaction Manager)-事务管理器：定义全局事务的范围、开始全局事务、提交或回滚全局事务。</li><li>RM(Resource Manager)-资源管理器：管理分支事务处理的资源，与TC交谈以注册分支事务和报告分支事务的状态，并驱动分支事务提交或回滚。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228213922.png" alt="image.png"></p><p>Seata 中有三种模式，分别是 XA、AT 和 TCC</p><ul><li>XA 模式</li><li>AT 模式</li><li>TCC 模式</li></ul><p><strong>XA 模式</strong></p><p>XA模式基于XA协议实现，是一种两阶段提交的分布式事务解决方案。XA模式涉及到事务管理器（TM）、资源管理器（RM）和事务协调者（TC）三个角色。</p><ul><li><strong>第一阶段（准备阶段）</strong>：事务管理器指示所有参与当前事务的资源管理器准备提交事务。</li><li><strong>第二阶段（提交/回滚阶段）</strong>：如果所有资源管理器都准备就绪，事务管理器会指示它们提交事务；如果任何资源管理器不能准备就绪，事务管理器会指示所有资源管理器回滚事务。</li></ul><p>XA模式保证了跨数据库和系统的事务一致性，但实现复杂，性能开销较大。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214142.png" alt="image.png"></p><p>AT 模式</p><p>AT模式是Seata自主创新的一种事务模式，全称为Automatic Transaction，即自动化事务模式。它通过对数据进行前后镜像记录来实现分布式事务。</p><ul><li><strong>提交事务</strong>：在事务提交时，如果执行成功，则直接提交事务；如果执行失败，利用镜像记录进行回滚。</li><li><strong>回滚事务</strong>：在回滚时，利用之前记录的前镜像和后镜像进行数据的恢复。</li></ul><p>AT模式不依赖XA协议，具有较好的性能，易于理解和使用，是Seata中使用最广泛的模式。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214546.png" alt="image.png"></p><p>TCC 模式</p><p>TCC模式即Try-Confirm-Cancel模式，是一种补偿性的事务模式。它将业务操作拆分为三个步骤：尝试（Try）、确认（Confirm）和取消（Cancel）。</p><ul><li><strong>Try阶段</strong>：检查并预留业务资源。</li><li><strong>Confirm阶段</strong>：如果所有服务的Try阶段都成功，那么执行业务操作。</li><li><strong>Cancel阶段</strong>：如果任何服务的Try阶段失败，那么执行撤销操作，释放在Try阶段预留的资源。</li></ul><p>TCC模式提供了较为灵活的事务控制能力，适用于对一致性要求高的业务场景。但是，开发成本较高，需要用户手动实现Try、Confirm和Cancel三个操作。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214636.png" alt="image.png"></p><p>总结；</p><ul><li><strong>XA模式</strong>：基于XA协议的两阶段提交，保证事务的ACID特性，实现复杂，性能开销大。</li><li><strong>AT模式</strong>：通过数据镜像记录实现分布式事务，简单易用，性能较好，是Seata的默认事务模式。</li><li><strong>TCC模式</strong>：通过显式的Try-Confirm-Cancel操作来控制事务，灵活性高，适合对一致性要求高的场景，但实现成本较高。</li></ul><p>暂时还不太理解，到时候就说一下关于分布式事务</p><p>其中一种解决方案是使用 Seata 进行一个分布式事务的管理，默认采用的是 AT 模式，事务提交的时候会保留一个数据快照，如果整个事务有执行失败的话，则执行回滚操作。（大致 Get 一下，详细的后面再了解一下）</p><p>关于其他的 AC、XA、TCC 是知道有这个，但具体不太清楚。然后角色记一下：TM 事务管理器，RM 资源管理器，TC 事务协调者。</p><hr><blockquote><p>MQ 🚩 💣</p></blockquote><p>需要看一下这个啥，分布式事务MQ 怎么试下难点</p><p>通过消息队列（MQ）实现分布式事务是一种常见的解决方案，这种方法通常被称为最终一致性方案或异步确保型方案。它利用消息队列的可靠性来保证分布式事务的一致性，主要应用于对实时性要求不是非常高，但对系统可用性和一致性要求较高的场景。</p><p>通过MQ实现分布式事务的基本思路是将事务的执行分成两个阶段：</p><ol><li><strong>本地事务执行</strong>：首先在发送方执行本地事务，并将要执行的跨服务操作封装成消息发送到消息队列中。此时，消息处于不可被消费状态。</li><li><strong>消息确认与消费</strong>：当本地事务成功提交后，消息变为可消费状态，接收方从消息队列中拉取消息并执行相应的操作。如果操作成功，完成整个分布式事务；如果操作失败，可以通过重试机制再次尝试，或者执行补偿操作以保证数据一致性。</li></ol><p>实现MQ分布式事务通常有两种方式：</p><ol><li><p><strong>半消息机制</strong>：这是一种较为复杂的实现方式，发送方首先发送一条“半消息”（即预备消息）到MQ，这条消息暂时不会被消费端消费。发送方执行本地事务，本地事务成功后再发送另一条确认消息给MQ，MQ收到确认消息后，将半消息标记为可消费，消费者此时可以正常消费这条消息。</p></li><li><p><strong>事务消息</strong>：某些MQ支持事务消息的特性，例如Apache RocketMQ。事务消息允许发送方在发送消息的同时执行本地事务，如果本地事务执行成功，则提交消息使其可被消费；如果本地事务执行失败，则回滚消息，使其不会被消费。</p></li></ol><h4 id="讲一下分布式事务-🚩" tabindex="-1">讲一下分布式事务 🚩 <a class="header-anchor" href="#讲一下分布式事务-🚩" aria-label="Permalink to &quot;讲一下分布式事务 🚩&quot;">​</a></h4><ul><li>为什么会产生分布式事务问题 <ul><li>无法使用本地事务来进行管理，需要引入分布式事务管理： <a href="https://blog.csdn.net/weapon_7/article/details/107008628" target="_blank" rel="noreferrer">https://blog.csdn.net/weapon_7/article/details/107008628</a></li></ul></li></ul><p>分布式事务是一个复杂但重要的问题。分布式事务指的是跨多个独立的服务或数据库实例的事务操作。</p><p>这些操作需要在不同的服务中保持数据一致性和可靠性。</p><p>常见的解决方案</p><ul><li>二阶段提交 2PC <ul><li>准备阶段 <ul><li>协调者向所有参与者发送准备请求，询问是否可以提交事务。</li><li>每个参与者执行事务操作，但不提交，并将操作结果告知协调者。</li></ul></li><li>提交阶段 <ul><li>如果所有参与者都同意提交，协调者向所有参与者发送提交请求，参与者提交事务。</li><li>如果有任一参与者不同意提交或超时未响应，协调者向所有参与者发送回滚请求，参与者回滚事务。</li></ul></li></ul></li><li>三阶段提交 3PC <ul><li>准备阶段 <ul><li>协调者询问参与者是否可以提交事务。</li></ul></li><li>预准备阶段 <ul><li>如果所有参与者都响应可以提交，协调者进入预提交阶段，参与者执行事务操作，但不提交。</li></ul></li><li>提交阶段 <ul><li>如果所有参与者都预提交成功，协调者发送提交请求，参与者提交事务。如果有参与者预提交失败，协调者发送回滚请求，参与者回滚事务。</li></ul></li></ul></li><li>本地事务和事件驱动（基于消息的最终一致性） <ul><li>本地事务 <ul><li>每个服务只管理自己的本地事务，确保操作要么完全成功，要么完全失败。</li></ul></li><li>事件驱动 <ul><li>服务之间通过事件总线（如 Kafka、RabbitMQ）发送和接收事件。一个服务完成本地事务后，发送事件通知其他服务。</li><li>接收服务处理事件并执行相应的本地事务操作。</li></ul></li></ul></li><li>TCC（Try-Confirm/Cancel）模式 <ul><li><strong>Try</strong>： <ul><li>尝试执行业务操作，预留资源，但不提交。</li></ul></li><li><strong>Confirm</strong>： <ul><li>确认操作，正式提交事务，只有在 Try 阶段成功时执行。</li></ul></li><li><strong>Cancel</strong>： <ul><li>取消操作，释放预留资源，只有在 Try 阶段失败或超时时执行</li></ul></li></ul></li></ul><p>2PC 的缺点是协调者是一个单点故障，并且网络分区或参与者的崩溃会导致事务挂起。</p><p>三阶段提交协议（3PC）是对 2PC 的改进，通过引入预提交阶段降低了协调者单点故障带来的影响</p><p>3PC 进一步降低了事务挂起的风险，但实现较为复杂。</p><h4 id="seata" tabindex="-1">Seata <a class="header-anchor" href="#seata" aria-label="Permalink to &quot;Seata&quot;">​</a></h4><p>Seata 的三个角色</p><ul><li><strong>TC</strong> (Transaction Coordinator) - 事务协调者：维护全局和分支事务的状态，驱动<strong>全局事务</strong>提交或回滚。</li><li><strong>TM</strong> (Transaction Manager) - 事务管理器：定义<strong>全局事务</strong>的范围，开始全局事务、提交或回滚全局事务。</li><li><strong>RM</strong> ( Resource Manager ) - 资源管理器：管理<strong>分支事务</strong>处理的资源( Resource )，与 TC 交谈以注册分支事务和报告分支事务的状态，并驱动<strong>分支事务</strong>提交或回滚。</li></ul><p>其中，TC 为单独部署的 <strong>Server</strong> 服务端，TM 和 RM 为嵌入到应用中的 <strong>Client</strong> 客户端</p><p>Seata 中有三种模式，分别是 XA、AT 和 TCC</p><ul><li>XA 模式</li><li>AT 模式</li><li>TCC 模式</li></ul><p><strong>XA 模式</strong></p><p>XA模式基于XA协议实现，是一种两阶段提交的分布式事务解决方案。XA模式涉及到事务管理器（TM）、资源管理器（RM）和事务协调者（TC）三个角色。</p><ul><li><strong>第一阶段（准备阶段）</strong>：事务管理器指示所有参与当前事务的资源管理器准备提交事务。</li><li><strong>第二阶段（提交/回滚阶段）</strong>：如果所有资源管理器都准备就绪，事务管理器会指示它们提交事务；如果任何资源管理器不能准备就绪，事务管理器会指示所有资源管理器回滚事务。</li></ul><p>XA模式保证了跨数据库和系统的事务一致性，但实现复杂，性能开销较大。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214142.png" alt="image.png"></p><p>AT 模式</p><p>AT模式是Seata自主创新的一种事务模式，全称为Automatic Transaction，即自动化事务模式。它通过对数据进行前后镜像记录来实现分布式事务。</p><ul><li><strong>提交事务</strong>：在事务提交时，如果执行成功，则直接提交事务；如果执行失败，利用镜像记录进行回滚。</li><li><strong>回滚事务</strong>：在回滚时，利用之前记录的前镜像和后镜像进行数据的恢复。</li></ul><p>AT模式不依赖XA协议，具有较好的性能，易于理解和使用，是Seata中使用最广泛的模式。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214546.png" alt="image.png"></p><p>TCC 模式</p><p>TCC模式即Try-Confirm-Cancel模式，是一种补偿性的事务模式。它将业务操作拆分为三个步骤：尝试（Try）、确认（Confirm）和取消（Cancel）。</p><ul><li><strong>Try阶段</strong>：检查并预留业务资源。</li><li><strong>Confirm阶段</strong>：如果所有服务的Try阶段都成功，那么执行业务操作。</li><li><strong>Cancel阶段</strong>：如果任何服务的Try阶段失败，那么执行撤销操作，释放在Try阶段预留的资源。</li></ul><p>TCC模式提供了较为灵活的事务控制能力，适用于对一致性要求高的业务场景。但是，开发成本较高，需要用户手动实现Try、Confirm和Cancel三个操作。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228214636.png" alt="image.png"></p><p>总结；</p><ul><li><strong>XA模式</strong>：基于XA协议的两阶段提交，保证事务的ACID特性，实现复杂，性能开销大。</li><li><strong>AT模式</strong>：通过数据镜像记录实现分布式事务，简单易用，性能较好，是Seata的默认事务模式。</li><li><strong>TCC模式</strong>：通过显式的Try-Confirm-Cancel操作来控制事务，灵活性高，适合对一致性要求高的场景，但实现成本较高。</li></ul><h4 id="半消息-rocketmq-二阶段提交" tabindex="-1">半消息 RocketMQ 二阶段提交 <a class="header-anchor" href="#半消息-rocketmq-二阶段提交" aria-label="Permalink to &quot;半消息 RocketMQ 二阶段提交&quot;">​</a></h4><p>通过消息队列（MQ）实现分布式事务是一种常见的解决方案，这种方法通常被称为最终一致性方案或异步确保型方案。它利用消息队列的可靠性来保证分布式事务的一致性，主要应用于对实时性要求不是非常高，但对系统可用性和一致性要求较高的场景。</p><p>通过MQ实现分布式事务的基本思路是将事务的执行分成两个阶段：</p><ol><li><strong>本地事务执行</strong>：首先在发送方执行本地事务，并将要执行的跨服务操作封装成消息发送到消息队列中。此时，消息处于不可被消费状态。</li><li><strong>消息确认与消费</strong>：当本地事务成功提交后，消息变为可消费状态，接收方从消息队列中拉取消息并执行相应的操作。如果操作成功，完成整个分布式事务；如果操作失败，可以通过重试机制再次尝试，或者执行补偿操作以保证数据一致性。</li></ol><p>实现MQ分布式事务通常有两种方式：</p><ol><li><p><strong>半消息机制</strong>：这是一种较为复杂的实现方式，发送方首先发送一条“半消息”（即预备消息）到MQ，这条消息暂时不会被消费端消费。发送方执行本地事务，本地事务成功后再发送另一条确认消息给MQ，MQ收到确认消息后，将半消息标记为可消费，消费者此时可以正常消费这条消息。</p></li><li><p><strong>事务消息</strong>：某些MQ支持事务消息的特性，例如Apache RocketMQ。事务消息允许发送方在发送消息的同时执行本地事务，如果本地事务执行成功，则提交消息使其可被消费；如果本地事务执行失败，则回滚消息，使其不会被消费。</p></li></ol><h3 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to &quot;分布式锁&quot;">​</a></h3><h4 id="分布式服务的接口幂等性如何设计" tabindex="-1">分布式服务的接口幂等性如何设计？ <a class="header-anchor" href="#分布式服务的接口幂等性如何设计" aria-label="Permalink to &quot;分布式服务的接口幂等性如何设计？&quot;">​</a></h4><p>幂等：多次调用方法或者接口不会改变业务状态，可以保证重复调用的结果和单次调用的结果一致。</p><p>需要幂等场景：</p><ul><li>1、用户重复点击（网络波动）、</li><li>2、MQ 消息重复</li><li>3、应用使用失败或者超时重试机制</li></ul><p>在 Restful API 的角度，看常见类型请求的幂等性分析：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228233944.png" alt="image.png"></p><p>token + redis</p><blockquote><p>分布式锁</p></blockquote><p>setnx + redission</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228234242.png" alt="image.png"></p><hr><p>问题：分布式服务的接口幂等性如何设计？</p><ul><li>幂等：多次调用方法或者接口不会改变业务状态，可以保证<strong>重复调用的结果和单次调用的结果一致</strong></li><li>如果是新增数据，可以使用数探库的难一素引</li><li>如果是新增或修改数据 <ul><li>分布式锁，性能较低</li><li>使用token + redis来实现，性能较好 <ul><li>第一次请求，生成一个唯一的 token 存入 redis ,返回给前端</li><li>第二次请求，业务处理，携带之前的 token,到 redis 进行验证，如果存在，可以执行业务，删除 token；如果不存在，则直接返回，不处理业务</li></ul></li></ul></li></ul><h4 id="讲一下分布式锁-🚩" tabindex="-1">讲一下分布式锁 🚩 <a class="header-anchor" href="#讲一下分布式锁-🚩" aria-label="Permalink to &quot;讲一下分布式锁 🚩&quot;">​</a></h4><h4 id="redisson-的可重入锁结构" tabindex="-1">Redisson 的可重入锁结构 <a class="header-anchor" href="#redisson-的可重入锁结构" aria-label="Permalink to &quot;Redisson 的可重入锁结构&quot;">​</a></h4><p>Redisson 的可重入结构是基于 Hash 结构的，具体的结构为</p><ul><li>key：锁的名词</li><li>value：持有锁的人，线程ID ： 重入次数</li></ul><h4 id="讲一下-redisson-的-看门狗机制" tabindex="-1">讲一下 Redisson 的 看门狗机制 <a class="header-anchor" href="#讲一下-redisson-的-看门狗机制" aria-label="Permalink to &quot;讲一下 Redisson 的 看门狗机制&quot;">​</a></h4><ul><li><p>1、在分布式系统下，对于共享资源的访问可以使用分布式锁，这里一般会考虑引入组件 redis ，然后使用 redis 中的 setnx 命令，这个命令的作用是 如果不存在则进行添加，如果存在则添加失败 setnx name value</p></li><li><p>2、一般这种情况下就可以实现一个简易的分布式锁，但是呢，有可能出现 redis 宕机的情况，这种情况下，为了防止这个 键值 一直存在 redis 中（锁），一般会进行添加一个有效时间，从而避免锁一直未释放的操作 setnx name value ex100；同时，这里如果是在过期时间内进行释放锁，会进行 删除操作，这里一般建议使用 Lua 命令进行操作（防止误删到其他的锁）</p></li><li><p>3、上面还可能出现一种情况，就是在过期时间后自动释放了锁，业务流程却未执行完，为了避免这种情况，建议引入 redission</p></li><li><p>当使用 Redisson 的锁机制（如 <code>RLock</code>）锁定某个资源时，如果没有显式地设置锁的租期（lease time），Redisson 会启用“看门狗”机制。这个机制的核心是自动续租，确保在持有锁的服务实例正常运行时，锁不会因为超时而被自动释放</p><ul><li><strong>默认租期设置</strong>：默认情况下，锁的租期设置为 30 秒。这意味着，如果在这段时间内没有操作完成，锁就会自动释放，防止死锁。</li><li><strong>自动续租</strong>：“看门狗”机制会在锁快到期时（默认情况下是租期的 1/3，即10秒后），自动发送一个命令给 Redis，将锁的租期重新延长到 30 秒。这个过程会一直持续，直到锁被显式释放。</li><li><strong>故障转移</strong>：如果持有锁的服务实例因为某些原因宕机或无法与 Redis 通信，锁将不会被续租，最终会在默认的租期结束后自动释放。这样，其他服务实例可以获取锁，继续处理任务，保证了系统的高可用性和一致性。</li></ul></li><li><p>waitTime：定义了尝试获取锁的最大等待时间。在等待时间内，如果锁释放了，当前线程可以成功获取锁；否则，获取锁失败。</p></li><li><p>leaseTime：定义了锁的持有时间。当持有时间到期后，锁会自动释放，防止死锁。如果设置为 <code>-1</code>，看门狗机制会启动，定期延长锁的有效期，直到显式释放锁。</p></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240407094353.png" alt="image.png"></p><h3 id="限流与监控" tabindex="-1">限流与监控 <a class="header-anchor" href="#限流与监控" aria-label="Permalink to &quot;限流与监控&quot;">​</a></h3><h4 id="你们项目中有没有做过限流-怎么做的" tabindex="-1">你们项目中有没有做过限流，怎么做的 <a class="header-anchor" href="#你们项目中有没有做过限流-怎么做的" aria-label="Permalink to &quot;你们项目中有没有做过限流，怎么做的&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281528174.png" alt="image.png"></p><p>限流的常见实现方式：</p><ul><li>1、Tomcat: 可以设置最大连接数 <ul><li>不过这种方式适合单体项目，分布式项目不太适合</li></ul></li><li>2、Nginx，漏桶算法</li><li>3、网关，令牌桶算法</li><li>4、自定义拦截器</li></ul><p>先掌握了解一下第二种和第三种方式</p><blockquote><p>面试题：你们项目中有没有做过限流，怎么做的。</p></blockquote><ul><li>1、先来介绍业务，什么情况下去做限流，需要说明QPS具体多少 <ul><li>我们当时有一个活动，到了假期就会抢购优惠券，QPS 最高可以达到2000，平时10-50之间，为了应对突发流量，需要做限流</li><li>常规限流，为了防止恶意攻击，保护系统正常运行，我们当时系统能够承受最大的QPS是多少（压测结果）</li></ul></li><li>2、nginx限流 <ul><li>控制速率（突发流量），使用的漏桶算法来实现过滤，让请求以固定的速率处理请求，可以应对突发流量</li><li>控制并发数，限制单个ip 的链接数和并发链接的总数</li></ul></li><li>3、网关限流 <ul><li>在spring cloud gateway中支持局部过滤器RequestRateLimiter来做限流，使用的是令牌桶算法，可以根据或路径进行限流，可以设置每秒填充平均速率，和令牌桶总容量。</li></ul></li></ul><blockquote><p>限流常见的算法有哪些呢</p></blockquote><p>可以讲一下令牌桶算法和漏桶算法。</p><blockquote><p>讲一些扩展内容</p></blockquote><p>1、一般通过什么做压测的</p><p>就讲使用 JMeter 即可</p><p>具体需要看实际使用 to be contined....</p><blockquote><p>Nginx 限流</p></blockquote><ul><li>控制访问请求速率</li><li>控制并发连接数（某个用户建立的连接数）</li></ul><p>Nginx提供了内置的模块来支持限流，如<code>limit_req_module</code>和<code>limit_conn_module</code>，它们可以帮助你根据请求速率或并发连接数来限制流量。</p><p>在实践中，通常会结合使用这两种方法来更全面地控制流量，确保服务既不会因为瞬时请求过多而崩溃，也不会因为过多并发连接而耗尽资源。</p><p>使用Nginx进行限流只是应对流量过载的一种手段，还需要结合应用层的限流、服务降级、熔断等策略来综合保障系统的稳定性和可用性。</p><blockquote><p>控制速率 limit_req_module</p></blockquote><p>可以理解Nginx 进行控制请求速率限制是类似漏桶算法的一种实现（应用了漏桶算法的思想）；</p><ol><li><strong>桶容量</strong>：算法中的“桶”有一个固定的容量，这个容量可以理解为系统能够承受的最大流量或请求速率的上限。</li><li><strong>入水速率</strong>：数据（或请求）以任意速率流入桶中。如果流入速率不定，那么这些数据会暂时存储在桶中，直到被处理。</li><li><strong>出水速率</strong>：数据以固定的速率从桶中“漏出”（即被处理）。出水速率是预先设定的，与实际流入速率无关。</li><li><strong>溢出处理</strong>：如果流入的数据量超过了桶的容量，即桶已满，那么超出的数据会被丢弃（或者触发其他的限流措施），这可以防止系统过载</li></ol><p>通过这种方式的限流，请求流量会以固定的速率从桶中“漏出”（即被处理）；如果流入的数据量超过了桶的容量，即桶已满，那么超出的数据会被丢弃。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281533917.png" alt="image.png"></p><p>使用<code>limit_req_module</code>进行请求速率限制</p><p><code>limit_req_module</code>模块允许你限制处理请求的速率，防止请求过多导致服务不可用。这个模块通常用于限制每个客户端的请求速率。</p><ol><li><strong>定义限流规则</strong>：首先，需要在Nginx配置中定义一个限流规则（<code>limit_req_zone</code>），指定限流的键（如客户端IP）、速率和存储区域大小。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    limit_req_zone $binary_remote_addr zone=mylimit:10m rate=1r/s;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里定义了一个名为<code>mylimit</code>的区域，大小为10MB，限制每个IP地址每秒最多只能处理1个请求。</p><p><strong>应用限流规则</strong>：然后，在需要限流的location或server上应用这个规则（<code>limit_req</code>）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        limit_req zone=mylimit burst=5;</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里在<code>/</code>位置应用了<code>mylimit</code>规则，并设置了<code>burst</code>参数为5，意味着允许在短时间内超过限制的请求被缓存起来，直到达到5个请求的限制。</p><blockquote><p>控制并发连接数</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281535314.png" alt="image.png"></p><p>使用<code>limit_conn_module</code>进行并发连接数限制</p><p><code>limit_conn_module</code>模块允许你限制并发连接数，这适用于限制每个客户端可以同时建立的连接数。</p><ol><li><strong>定义连接数限制</strong>：同样，首先定义一个限制区域（<code>limit_conn_zone</code>）。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    limit_conn_zone $binary_remote_addr zone=connlimit:10m;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里定义了一个名为<code>connlimit</code>的区域，大小为10MB，用于存储并发连接数的状态。</p><ol start="2"><li><strong>应用连接数限制</strong>：在需要限制的location或server上应用这个规则（<code>limit_conn</code>）。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        limit_conn connlimit 10;</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里在<code>/</code>位置应用了<code>connlimit</code>规则，限制每个IP最多可以同时建立10个连接。</p><hr><blockquote><p>网关限流 🚩</p></blockquote><p>网关限流一般是使用 Spring Cloud Gateway 来实现网关层面的流量控制。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402281639179.png" alt="image.png"></p><p>围绕网关限流可用先回答一下项目是如何做的：比如说是：利用<code>RequestRateLimiter</code>过滤器，结合Redis来存储和管理限流数据。</p><p>然后说一下配置文件中的参数中是应用了令牌桶算法的思想</p><p>还可以结合 Gateway + Sentinel 实现流控（带过）</p><blockquote><p>令牌桶算法</p></blockquote><p>令牌桶算法（Token Bucket Algorithm）是一种流量控制算法，广泛应用于网络流量整形（Traffic Shaping）和速率限制（Rate Limiting）中。该算法的核心思想是以恒定的速率向桶中添加令牌（token），请求消耗令牌才能被处理，如果桶中没有令牌，则请求被限制。</p><p>基本原理</p><ol><li><strong>令牌桶</strong>：有一个固定容量的桶，系统以固定速率往桶里添加令牌。如果桶满了，则新添加的令牌会被丢弃。</li><li><strong>请求处理</strong>：每个传入的请求需要从桶中取出一定数量的令牌。如果桶中的令牌足够，请求被处理，同时从桶中移除对应数量的令牌；如果桶中令牌不足，请求则根据策略（如排队、立即拒绝等）处理。</li><li><strong>恒定速率</strong>：令牌以恒定的速率r被添加到桶中。这个速率r决定了请求被允许的最大平均速率。</li><li><strong>突发流量</strong>：桶的容量允许在短时间内处理突发流量。如果桶中有足够的令牌，超过平均速率r的请求可以立即被处理，直到桶中的令牌被耗尽。</li></ol><p>在Spring Cloud Gateway中使用Redis RateLimiter实现限流时，其背后的原理就借鉴了令牌桶算法。</p><p>通过定义<code>replenishRate</code>和<code>burstCapacity</code>参数，分别对应令牌添加的速率和桶的容量，从而实现对网关流量的细粒度控制。当请求到达网关时，会尝试从Redis中的令牌桶获取令牌，如果获取成功，则请求被允许通过；如果令牌不足，则请求被限流。</p><ul><li>令牌添加速率</li><li>桶容量</li></ul><hr><p>具体使用示例：</p><blockquote><p>Gateway 网关限流</p></blockquote><ul><li>1、在Spring Cloud Gateway中实现网关限流，我们通常会利用<code>RequestRateLimiter</code>过滤器，结合Redis来存储和管理限流数据。</li><li>2、还有一种是 Gateway + Sentinel 结合实现流量控制</li></ul><p>这里说一下第一种，第二种感觉引入组件造成系统复杂度提升，并没有采用（从这个角度回答）</p><p>第一种方式</p><p>以下是一个基于Spring Cloud Gateway与Redis实现网关限流的示例。</p><ul><li>1、添加Spring Cloud Gateway和Spring Boot Redis的依赖</li><li>2、配置 Redis</li><li>3、定义限流规则</li></ul><p>在Spring Cloud Gateway中通过配置文件定义路由和限流规则。在这个示例中，我们为<code>/api/myService/**</code>路径配置了限流规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - id: myservice_route</span></span>
<span class="line"><span>          uri: lb://MY-SERVICE # 假设MY-SERVICE是你的微服务名称</span></span>
<span class="line"><span>          predicates:</span></span>
<span class="line"><span>            - Path=/api/myService/**</span></span>
<span class="line"><span>          filters:</span></span>
<span class="line"><span>            - name: RequestRateLimiter</span></span>
<span class="line"><span>              args:</span></span>
<span class="line"><span>                # 每秒钟允许通过的请求数</span></span>
<span class="line"><span>                redis-rate-limiter.replenishRate: 10</span></span>
<span class="line"><span>                # 用户在一秒钟内可以突发的请求数量</span></span>
<span class="line"><span>                redis-rate-limiter.burstCapacity: 20</span></span>
<span class="line"><span>                # 使用SpEL表达式来确定限流的key</span></span>
<span class="line"><span>                key-resolver: &quot;#{@ipKeyResolver}&quot;</span></span></code></pre></div><ol start="4"><li>实现KeyResolver</li></ol><p><code>key-resolver</code>用于确定限流的维度，例如可以按IP地址限流。下面是按IP地址限流的<code>KeyResolver</code>实现。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.springframework.cloud.gateway.filter.ratelimit.KeyResolver;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Bean;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Configuration;</span></span>
<span class="line"><span>import org.springframework.web.server.ServerWebExchange;</span></span>
<span class="line"><span>import reactor.core.publisher.Mono;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class RateLimiterConfiguration {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    KeyResolver ipKeyResolver() {</span></span>
<span class="line"><span>        return new KeyResolver() {</span></span>
<span class="line"><span>            @Override</span></span>
<span class="line"><span>            public Mono&lt;String&gt; resolve(ServerWebExchange exchange) {</span></span>
<span class="line"><span>                // 从请求中获取IP地址，作为限流的key</span></span>
<span class="line"><span>                return Mono.just(exchange.getRequest().getRemoteAddress().getAddress().getHostAddress());</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ol start="5"><li>启动并测试</li></ol><p>启动Spring Cloud Gateway应用，并向<code>/api/myService/**</code>路径发送请求来测试限流效果。</p><p>如果请求速率超过了定义的<code>replenishRate</code>和<code>burstCapacity</code>，超出限流条件的请求将会收到429 Too Many Requests响应。</p><p>注意事项</p><ul><li>实际部署时，Redis的配置应根据你的环境进行调整，包括考虑Redis集群等高可用配置。</li><li>限流参数<code>replenishRate</code>和<code>burstCapacity</code>应根据实际业务场景合理设置，避免过度限流影响用户体验。</li><li><code>key-resolver</code>的实现可以根据实际需要选择不同的限流维度，除了IP地址外，还可以按用户ID、API路径等维度进行限流。</li></ul><h4 id="你们项目服务监控怎么做的" tabindex="-1">你们项目服务监控怎么做的 <a class="header-anchor" href="#你们项目服务监控怎么做的" aria-label="Permalink to &quot;你们项目服务监控怎么做的&quot;">​</a></h4><p>为什么需要监控</p><p>一般目的是为了：</p><ul><li>问题定位</li><li>性能分析</li><li>服务关系</li><li>服务告警</li></ul><p>监控工具</p><ul><li>Springboot-admin</li><li>prometheus+Grafana</li><li>链路工具 <ul><li>zipkin</li><li>skywalking</li></ul></li></ul><blockquote><p>大概看一下这个用法：prometheus+Grafana</p></blockquote><p>如果实际问到，就回答自己回答有这个监控方式，以及如何使用的。</p><p>Prometheus和Grafana是一对强大的监控和可视化工具组合，广泛用于监控微服务架构中的应用和基础设施的健康状况、性能指标等。这种组合的用法主要涉及到三个步骤：数据收集（Prometheus），数据存储（Prometheus），以及数据可视化（Grafana）。</p><blockquote><p>步骤1: 数据收集</p></blockquote><p>Prometheus通过拉模式（pull）或推模式（push，需要使用Pushgateway）从应用程序和基础设施中收集指标数据。通常，应用程序和服务会暴露一个HTTP端点（通常是<code>/metrics</code>），Prometheus定时从这些端点抓取（scrape）数据。</p><p>为了让Prometheus能够收集数据，你需要在Prometheus的配置文件（通常是<code>prometheus.yml</code>）中定义抓取目标和频率。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>  - job_name: &#39;spring-application&#39;</span></span>
<span class="line"><span>    scrape_interval: 15s</span></span>
<span class="line"><span>    metrics_path: &#39;/actuator/prometheus&#39;</span></span>
<span class="line"><span>    static_configs:</span></span>
<span class="line"><span>      - targets: [&#39;localhost:8080&#39;]</span></span></code></pre></div><p>数据采集这里要求 SpringBoot 应用对外开发 <code>/metrics</code> 接口，实际操作通常是通过<strong>集成Spring Boot Actuator和Micrometer来实现的</strong>。 🚩</p><p>Spring Boot Actuator提供了一系列内置的端点，包括<code>/metrics</code>，用于监控和管理应用。Micrometer则作为Spring Boot的维度化指标库，充当了应用和监控系统之间的桥梁。</p><ul><li>引入依赖：确保在Spring Boot项目的<code>pom.xml</code>文件中引入了Spring Boot Actuator和Micrometer Prometheus的依赖。</li><li>配置应用：确保<code>application.properties</code>或<code>application.yml</code>配置文件中启用了<code>/metrics</code>端点。Spring Boot 2.x默认启用了大部分Actuator端点，包括<code>/metrics</code>。</li><li>暴露/metrics端点</li><li>也可以自定义指标</li></ul><blockquote><p>步骤2: 数据存储</p></blockquote><p>Prometheus会将收集到的数据存储在本地的时间序列数据库中。Prometheus的存储引擎专为时间序列数据优化，支持高效的数据存储、查询和管理。</p><blockquote><p>步骤3: 数据可视化</p></blockquote><p>Grafana是一个开源的数据可视化工具，支持从多种数据源（包括Prometheus）查询和展示数据。要使用Grafana展示Prometheus的数据，你需要：</p><ol><li><strong>安装并启动Grafana</strong>：下载并安装Grafana，然后启动Grafana服务。</li><li><strong>配置数据源</strong>：登录Grafana的Web界面，添加一个新的数据源，选择Prometheus作为类型，并配置Prometheus服务器的URL。</li><li><strong>创建仪表板</strong>：在Grafana中创建新的仪表板，可以添加多种类型的面板（如图表、表格、单值指标等）来展示Prometheus收集的指标数据。</li><li><strong>查询和展示数据</strong>：在仪表板的面板中，使用PromQL（Prometheus查询语言）编写查询，从Prometheus中检索数据，并根据需求配置面板的显示方式。</li></ol><hr><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><h4 id="你们项目中日志管理怎么做的" tabindex="-1">你们项目中日志管理怎么做的 <a class="header-anchor" href="#你们项目中日志管理怎么做的" aria-label="Permalink to &quot;你们项目中日志管理怎么做的&quot;">​</a></h4><p>这部分先不管，大概说一下，实际项目中的一种解决方案是怎么做的就行</p><p>to be contined....</p><p>后续打算优化可用看一下这篇文章： <a href="https://www.yuque.com/snailclimb/mf2z3k/ma1byh" target="_blank" rel="noreferrer">https://www.yuque.com/snailclimb/mf2z3k/ma1byh</a></p>`,405)])])}const h=n(e,[["render",p]]);export{d as __pageData,h as default};
